head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
eval함수는 자동변환에 제약이 많습니다. ASIS소스 확인 후 변환해주세요.
eval함수 사용 수: 5

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
scwin.vScrenID = "ULDBNS25600.xml";

// grid resize 시작부
frame.SetEvent("onwinstat", OnWinStat);
scwin.iTimer = 0;
scwin.maxval = 0;
scwin.gOldWidthSize = frame.width;
scwin.gNewWidthSize = 0;
scwin.isCtrl = false;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.sleep = function(numberMillis) {
    var now = new Date();
    var exitTime = now.getTime() + numberMillis;
    while (true) {
        now = new Date();
        if (now.getTime() > exitTime) return;
    }

};
scwin.OnSized = function(winID) {
    if (scwin.iTimer > 0) window.clearInterval(scwin.iTimer);
    scwin.iTimer = 0;
    scwin.gNewWidthSize = frame.width;
    scwin.GauceObjResize(frame.width, frame.height);
};
scwin.OnSizedMax = function(winID) {
    if (scwin.iTimer > 0) window.clearInterval(scwin.iTimer);
    scwin.iTimer = 0;
    scwin.maxval = 0;
    scwin.GauceObjResize($c.frame.path("/").width, frame.height);
};
scwin.OnWinStat = function(winID, statmsg) {
    if (statmsg == "activate" && winID.substring(0, 6) == "Child_") {
        $c.frame.path("/").WinActive(winID, statmsg);
    }
    if (statmsg == "maximize") {
        scwin.maxval = 1;
    } else if (statmsg == "size") {
        if (scwin.maxval == 0) {
            var strFnc = "OnSized('" + winID + "')";
            if (scwin.iTimer > 0) {
                window.clearInterval(scwin.iTimer);
                scwin.iTimer = 0;
            }
            scwin.iTimer = window.setInterval(strFnc, 300);
        } else if (scwin.maxval == 1) {
            scwin.OnSizedMax(winID);
            scwin.gOldWidthSize = $c.frame.path("/").width - 10;
        }
    }
};
scwin.GauceObjResize = function(a, b) {
    // 그리드메인
    var gw = (a - parseInt(grd_List.getStyle("width")) - 30);
    grd_List.ReDraw = "false";
    grd_List.setGridWidth(parseInt(grd_List.getStyle("width")) + gw);
    grd_List.ReDraw = "true";
    scwin.gOldWidthSize = frame.width;

    // 탭패널
    var pnl_main_grp = document.all("__GROUPBOX_BACKGROUND__" + "panel_Top");
    pnl_main_grp.style.setGridWidth(parseInt(pnl_main_grp.style.width.replace("px", "")) + gw); // 상단패널
    panel_Top.style.width = parseInt(panel_Top.style.width.replace("px", "")) + gw;
};


// grid resize 종료부


scwin.fr_SecuGrpId = SECUGRP_ID_EW;
scwin.fn_RefreshForm = function(interval) {
    setInterval("fn_search();", interval);
};



/********************************************** 
 * 설명       : 조회버튼 클릭
 ***********************************************/
scwin.fn_search = function() {
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_ACPT_STAT_LIST";
    url += "&queryId=lds.stf.bnsacpt_stat.select.list";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_CO_NM=" + $c.stf.getObjectValue(txb_com_abbrv);
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
    $c.cm.ShowWin(grd_List);
};



/********************************************** 
 * 함수명  	 : fn_SetBgColor_list
 * 설명       : 수신내역 목록의 배경색 설정
 ***********************************************/
scwin.fn_SetBgColor_list = function() {
    //적용희망일과 적용일 불일치시 컬럼의 배경색 RED로 설정

    $c.cm.setColumnProp(grd_List, 'PROCS_REQ_DD', 'BgColor', "{decode(STRT_DD           ,'',decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff'),decode(PROCS_REQ_DD,STRT_DD,decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff'),'#E96A6A'))}");
    $c.cm.setColumnProp(grd_List, 'STRT_DD', 'BgColor', "{decode(STRT_DD            ,'',decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff'),decode(PROCS_REQ_DD,STRT_DD,decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff'),'#E96A6A'))}");


    //grd_List.ColumnProp('PROCS_REQ_DD', 'BgColor') = "{decode(PROCS_REQ_DD,'',decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff'),decode(PROCS_REQ_DD,STRT_DD,decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff'),'#E96A6A'))}";
    //grd_List.ColumnProp('PROCS_REQ_DD', 'BgColor') = "{decode(STRT_DD           ,'',decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff'),decode(PROCS_REQ_DD,STRT_DD,decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff'),'#E96A6A'))}";
    //grd_List.ColumnProp('STRT_DD', 'BgColor')            = "{decode(PROCS_REQ_DD,'',decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff'),decode(PROCS_REQ_DD,STRT_DD,decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff'),'#E96A6A'))}";
    //grd_List.ColumnProp('STRT_DD', 'BgColor')            = "{decode(STRT_DD            ,'',decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff'),decode(PROCS_REQ_DD,STRT_DD,decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff'),'#E96A6A'))}";

};








/********************************************** 
 * 함수명  	 : fn_SetApplTime
 * 설명       : 신청시간종료 안내문구 조정
 ***********************************************/
scwin.fn_SetApplTime = function() {
    var clientnow = new Date();

    /* 오늘 날짜를 구한다 */
    var curYear = clientnow.getYear();
    var curMonth = (clientnow.getMonth()) + 1;
    var curDay = clientnow.getDate();
    var hours = clientnow.getHours();
    var minutes = clientnow.getMinutes();
    var seconds = clientnow.getSeconds();
    if (eval(hours) >= 9 && eval(hours) < 17) {
        //9~17시
        $c.stf.showObj(label_5, true);
        $c.stf.showObj(label_9, true);
        $c.stf.showObj(label_10, false);
        $c.stf.showObj(label_11, false);
    } else if (eval(hours) == 17) {
        //17~18시
        $c.stf.showObj(label_5, false);
        $c.stf.showObj(label_9, true);
        $c.stf.showObj(label_10, true);
        $c.stf.showObj(label_11, false);
    } else if (eval(hours) < 9 || eval(hours) >= 18) {
        //9시 이전 or 18시 이후
        $c.stf.showObj(label_5, false);
        $c.stf.showObj(label_9, false);
        $c.stf.showObj(label_10, true);
        $c.stf.showObj(label_11, true);
    }
};




/********************************************** 
 * 함수명   : fn_GetParIsurCd
 * 설명       : 발행기관 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsurCd = function(arrPar) {
    arrPar[0] = {
        ISUR_CD: $c.stf.getObjectValue(txb_com_abbrv)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


